// (ERROR_REASON_REAUTHENTICATION_REQUIRED). Each change and its platform
// audit entry are written in one transaction; the entry reaches identity's
// platform_audit_logs through core's outbox (PlatformAuditService).
type AdminServiceServer interface {
	// SearchTayfas lists tayfas whose name contains the query (case- and
	// Turkish-insensitive), newest first; deleted ones included. At most 50.
	SearchTayfas(context.Context, *SearchTayfasRequest) (*SearchTayfasResponse, error)
	// GetTayfa returns a tayfa's metadata, its admins and moderators.
	GetTayfa(context.Context, *AdminServiceGetTayfaRequest) (*AdminServiceGetTayfaResponse, error)
	// ListTayfaMembers lists a tayfa's memberships and roles (at most 500).
	ListTayfaMembers(context.Context, *ListTayfaMembersRequest) (*ListTayfaMembersResponse, error)
	// ListUserTayfas lists the tayfas a user is an active member of.
	ListUserTayfas(context.Context, *ListUserTayfasRequest) (*ListUserTayfasResponse, error)
	// SuspendTayfa makes the tayfa read-only; its admins and moderators get
	// a notification and see the reason in the tayfa's details;
	// tayfa.suspended goes to chat.
	SuspendTayfa(context.Context, *SuspendTayfaRequest) (*SuspendTayfaResponse, error)
	// UnsuspendTayfa lifts the suspension.
	UnsuspendTayfa(context.Context, *UnsuspendTayfaRequest) (*UnsuspendTayfaResponse, error)
	// DeleteTayfa soft deletes the tayfa at once (no 72-hour wait) and sends
	// tayfa.deleted; it is purged 30 days later like any deleted tayfa.
	DeleteTayfa(context.Context, *AdminServiceDeleteTayfaRequest) (*AdminServiceDeleteTayfaResponse, error)
	// SetMemberRole changes an active member's role: making someone admin of
	// a tayfa left without an active admin, or correcting roles after abuse.
	// The last-admin rule still holds (ERROR_REASON_LAST_ADMIN).
	SetMemberRole(context.Context, *SetMemberRoleRequest) (*SetMemberRoleResponse, error)
	// ListPlatformReports is the platform's queue: reports escalated to the
	// platform, open first; within them minor_involved and child_safety
	// first, then oldest first.
	ListPlatformReports(context.Context, *ListPlatformReportsRequest) (*ListPlatformReportsResponse, error)
	// GetReportedItem returns the reported item only, and records the viewing
	// in the platform audit log.
	GetReportedItem(context.Context, *GetReportedItemRequest) (*GetReportedItemResponse, error)
	// GetReportEvidencePhotoUrl returns a GET link, valid for 5 minutes, to a
	// direct message report's evidence photo (issue #205, ADR-0031), and
	// records the opening in the platform audit log
	// (report.view_evidence_photo). It is signed only when asked: a read of
	// the report carries has_evidence_photo, never the link. A report
	// without one, or without object storage, is ERROR_REASON_REPORT_NOT_FOUND.
	GetReportEvidencePhotoUrl(context.Context, *GetReportEvidencePhotoUrlRequest) (*GetReportEvidencePhotoUrlResponse, error)
	// GetReportedMessagePhotoUrl returns a GET link, valid for 5 minutes, to
	// the photo of a reported channel message (issue #205, ADR-0031), and
	// records the opening in the platform audit log
	// (report.view_message_photo). It is signed only when asked: a read of
	// the report carries has_message_photo, never the link. The photo is
	// there while the message holds it; a report without one, a photo
	// already gone, or no object storage is ERROR_REASON_REPORT_NOT_FOUND.
	GetReportedMessagePhotoUrl(context.Context, *GetReportedMessagePhotoUrlRequest) (*GetReportedMessagePhotoUrlResponse, error)
	// DecideReport records the platform's decision on an escalated report.
	DecideReport(context.Context, *DecideReportRequest) (*DecideReportResponse, error)
	// GetStats returns the panel dashboard's tayfa counts and the last run of
	// each background job (issue #110). Counts and times only.
	GetStats(context.Context, *GetStatsRequest) (*GetStatsResponse, error)
	// ListDiscoverQueue lists the tayfas waiting for a Keşfet decision:
	// PENDING applications and DROPPED tayfas, oldest first, at most 200.
	// Metadata and counts only.
	ListDiscoverQueue(context.Context, *ListDiscoverQueueRequest) (*ListDiscoverQueueResponse, error)
	// ApproveDiscover approves a PENDING or DROPPED tayfa for Keşfet. It is
	// listed while its admins keep Keşfet on and the listing rules hold.
	//
	// Errors: ERROR_REASON_TAYFA_NOT_FOUND, ERROR_REASON_TAYFA_STATE_CONFLICT
	// (no application, or already approved or rejected),
	// ERROR_REASON_REASON_REQUIRED, ERROR_REASON_REAUTHENTICATION_REQUIRED.
	ApproveDiscover(context.Context, *ApproveDiscoverRequest) (*ApproveDiscoverResponse, error)
	// RejectDiscover declines an application or takes an approved or dropped
	// tayfa out of Keşfet.
	//
	// Errors: as ApproveDiscover (STATE_CONFLICT: no application, or already
	// rejected).
	RejectDiscover(context.Context, *RejectDiscoverRequest) (*RejectDiscoverResponse, error)
	// GetCatalogAdmin returns the whole catalog as the panel manages it:
	// retired entries too, with the definitions, presets' rules and the
	// blocked domain list.
	GetCatalogAdmin(context.Context, *GetCatalogAdminRequest) (*GetCatalogAdminResponse, error)
	// SaveCatalogInterest creates or changes an interest. default_widgets
	// must be home page widgets that need no settings.
	SaveCatalogInterest(context.Context, *SaveCatalogInterestRequest) (*SaveCatalogInterestResponse, error)
	// SaveCatalogEventType creates (type.version 0) or changes (type.version
	// = the version the change was made on) an event type. A change of the
	// name, icon, modes or definition makes a new version; old events keep
	// theirs (ADR-0025 §2). The interests, position and status are not part
	// of a version. A new interest of a type must be active.
	SaveCatalogEventType(context.Context, *SaveCatalogEventTypeRequest) (*SaveCatalogEventTypeResponse, error)
	// SaveCatalogBadge creates or changes a badge definition
	// (catalog.CheckBadge). Its scope, rule kind and period never change.
	SaveCatalogBadge(context.Context, *SaveCatalogBadgeRequest) (*SaveCatalogBadgeResponse, error)
	// SaveCatalogStudyTag creates or changes a study tag. Its parent never
	// changes. A new level or subject gets its "Diğer" child
	// (<key>_other) in the same save; the list must pass
	// catalog.CheckStudyTags afterwards.
	SaveCatalogStudyTag(context.Context, *SaveCatalogStudyTagRequest) (*SaveCatalogStudyTagResponse, error)
	// SaveCatalogScorePreset creates or changes a score preset. Tables
	// already set up keep the rules they were set up with.
	SaveCatalogScorePreset(context.Context, *SaveCatalogScorePresetRequest) (*SaveCatalogScorePresetResponse, error)
	// BlockDomain adds a domain (and so its subdomains) to the blocked
	// domain list (ADR-0040 §3): new links to it are refused and existing
	// materials with it are hidden, not deleted.
	//
	// Errors: ERROR_REASON_VALIDATION (domain: not a host name, or already
	// on the list), ERROR_REASON_REASON_REQUIRED,
	// ERROR_REASON_REAUTHENTICATION_REQUIRED.
	BlockDomain(context.Context, *BlockDomainRequest) (*BlockDomainResponse, error)
	// UnblockDomain removes a domain from the list; its materials show
	// again.
	//
	// Errors: ERROR_REASON_VALIDATION (domain: not on the list), and as
	// BlockDomain.
	UnblockDomain(context.Context, *UnblockDomainRequest) (*UnblockDomainResponse, error)
	mustEmbedUnimplementedAdminServiceServer()
}

